let state=loadState(),journalFilter="Alle",heroRollMode="normal",heroTab="overview",editingAttack=-1,editingAbility=-1,editingSkills=false,levelDraft=null,mapScale=1;
let creationMode="points",creationStats={STR:8,DEX:8,CON:8,INT:8,WIS:8,CHA:8},creationRollDetails={},creationSkills=[];
function deepClone(x){return JSON.parse(JSON.stringify(x));}
function safeText(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));}
function attrMod(n){return Math.floor((Number(n)-10)/2)}function fmt(n){return Number(n)>=0?"+"+Number(n):String(Number(n))}function currentHero(){return state.heroes.find(h=>h.id===state.current)}function baseHeroById(id){return BASE_HEROES.find(h=>h.id===id)}
const DICE_SIDES=[4,6,8,10,12,20];function diceAsset(sides){const n=Number(sides);return DICE_SIDES.includes(n)?n:20}function diceIcon(sides,cls='dice-inline'){const n=diceAsset(sides);return `<img class="${cls}" src="dice-w${n}-v55.webp" alt="W${n}">`}function valueIcon(key,cls='value-icon'){return `<img class="${cls}" src="help-${String(key).toLowerCase()}-v53.webp" alt="">`}function layoutIcon(key,cls='layout-icon'){const special={INVENTORY:'icons-backpack-v42.webp',JOURNAL:'icons-journal-v42.webp',MAP:'icons-map-v42.webp'};const src=special[key]||`help-${String(key).toLowerCase()}-v53.webp`;return `<img class="${cls}" src="${src}" alt="">`}
function profForLevel(l){return l>=17?6:l>=13?5:l>=9?4:l>=5?3:2}
function xpInfo(h){const level=Math.max(1,Math.min(20,Number(h.level)||1)),xp=Math.max(0,Math.round(Number(h.xp)||0)),base=XP_THRESHOLDS[level]||0,next=level<20?XP_THRESHOLDS[level+1]:null,pct=next===null?100:Math.max(0,Math.min(100,Math.round((xp-base)/(next-base)*100)));return{level,xp,base,next,pct,remaining:next===null?0:Math.max(0,next-xp),ready:next!==null&&xp>=next}}
function numberDE(n){return Number(n||0).toLocaleString('de-DE')}
function renderXpBar(h,editable=false){const x=xpInfo(h),status=x.next===null?'Höchste Stufe erreicht':x.ready?`Stufe ${x.level+1} bereit`:`Noch ${numberDE(x.remaining)} EP bis Stufe ${x.level+1}`;return `<div class="xp-card ${x.ready?'xp-ready':''}"><div class="xp-heading"><span>${valueIcon('LEVEL')}<b>Erfahrung</b></span><strong>Stufe ${x.level}</strong></div><div class="xp-track"><div class="xp-fill" style="width:${x.pct}%"></div></div><div class="xp-meta"><span>${numberDE(x.xp)} EP</span><span>${status}</span></div>${editable?`<div class="xp-editor"><label>Gesamte EP<input id="gameXpInput" type="number" inputmode="numeric" min="0" value="${x.xp}"></label><button class="gold" onclick="saveHeroXp()">EP speichern</button></div>${x.ready?'<button class="wide xp-level-button" onclick="startLevelUpFromGameMode()">Stufenaufstieg vorbereiten</button>':''}`:''}</div>`}
function normalizeState(s){s=s||{};s.heroes=s.heroes||deepClone(BASE_HEROES);s.journal=s.journal||[];s.rollHistory=s.rollHistory||[];const byId=new Map(BASE_HEROES.map(h=>[h.id,h]));s.heroes=s.heroes.map(h=>{const b=byId.get(h.id);const out=b?Object.assign(deepClone(b),h):Object.assign({image:"backgrounds-cosmic-v42.webp",story:"",notes:"",attacks:[],abilities:[],inventory:[],proficiencies:[],level:1,prof:2,hp:10,maxHp:10,ac:10,speed:9,stats:{STR:10,DEX:10,CON:10,INT:10,WIS:10,CHA:10}},h);out.level=out.level||1;out.prof=out.prof||profForLevel(out.level);out.xp=Number.isFinite(Number(out.xp))?Math.max(0,Math.round(Number(out.xp))):(XP_THRESHOLDS[out.level]||0);return out});for(const b of BASE_HEROES)if(!s.heroes.some(h=>h.id===b.id)){const fresh=deepClone(b);fresh.xp=XP_THRESHOLDS[fresh.level]||0;s.heroes.push(fresh)}return s}
function loadState(){for(const key of [STORAGE_KEY,"eldanorV5","eldanorV42","eldanorV4","eldanorV3"]){try{const v=JSON.parse(localStorage.getItem(key)||"null");if(v)return normalizeState(v)}catch(e){}}return {heroes:deepClone(BASE_HEROES),current:null,journal:[],rollHistory:[]}}
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}
function skillBonus(h,s){const a=SKILLS[s]||"WIS";return attrMod(h.stats[a])+(h.proficiencies.includes(s)?Number(h.prof||0):0)}
function switchView(id){document.querySelectorAll(".view,.bottom-nav button").forEach(x=>x.classList.remove("active"));document.getElementById(id).classList.add("active");const b=document.querySelector(`.bottom-nav button[data-v="${id}"]`);if(b)b.classList.add("active");if(id==="journal")renderNotes();if(id==="more")renderParty();if(id==="map")setTimeout(()=>fitMapIfNeeded(),30)}
document.querySelectorAll(".bottom-nav button").forEach(b=>b.onclick=()=>switchView(b.dataset.v));
function openHeroChooser(){renderChooser();document.getElementById("chooser").classList.add("open");document.getElementById("chooserClose").style.visibility=currentHero()?"visible":"hidden"}
function closeOverlay(id){document.getElementById(id).classList.remove("open");if(id==="helpOverlay")document.body.classList.remove("sheet-open")}
function renderChooser(){const el=document.getElementById("chooserGrid");el.innerHTML=state.heroes.map(h=>`<button class="hero-choice ${h.id===state.current?'selected':''}" onclick="chooseHero('${h.id}')"><img src="${h.image}" alt="${safeText(h.name)}"><span class="hc-info"><strong>${safeText(h.name)}</strong><small>${safeText(h.role)} · Stufe ${h.level||1}</small></span></button>`).join("");setTimeout(()=>{const s=el.querySelector(".selected");if(s)s.scrollIntoView({behavior:"smooth",inline:"center",block:"nearest"})},60)}
function chooseHero(id){state.current=id;heroTab="overview";save();closeOverlay("chooser");renderHero();renderNotes();renderParty();renderGameMode();switchView("hero")}
function setHeroTab(tab){heroTab=tab;editingAttack=-1;editingAbility=-1;levelDraft=null;renderHero()}
function helpAttrCard(k,v){return `<div class="attr help-tappable" data-help="${k}">${valueIcon(k)}<small>${ATTR_NAMES[k]}</small><strong>${v}</strong><em>${fmt(attrMod(v))}</em></div>`}
function renderHero(){const h=currentHero(),el=document.getElementById("myHero");if(!h){el.innerHTML=`<div class="feature-banner"><img src="backgrounds-cosmic-v42.webp"><div class="overlayText"><small>WILLKOMMEN</small><h2>Eldanor</h2><p>Wähle zuerst deinen Helden.</p><button class="gold" onclick="openHeroChooser()">Charakterwahl</button></div></div>`;document.getElementById("headerHero").textContent="Chroniken einer erwachenden Welt";return}document.getElementById("headerHero").textContent=h.name+" · "+h.role;const tabs=[["overview","Übersicht","PROF"],["skills","Fertigkeiten","SKILL"],["attacks","Angriffe","ATTACK"],["abilities","Fähigkeiten","ABILITY"],["inventory","Inventar","INVENTORY"]].map(([id,t,icon])=>`<button class="${heroTab===id?'on':''}" onclick="setHeroTab('${id}')">${layoutIcon(icon)}<span>${t}</span></button>`).join("");el.innerHTML=`<div class="hero-cover"><img src="${h.image}" alt="${safeText(h.name)}"><div class="hero-cover-info"><h2>${safeText(h.name)}</h2><p>${safeText(h.role)} · Stufe ${h.level||1}</p><div class="hero-story">${safeText(h.story||"")}</div><div class="cover-actions"><button onclick="openHeroChooser()">Charakterwahl</button><button onclick="openGameMode()">Spielmodus</button><button onclick="openBasicEdit()">Held bearbeiten</button><button onclick="openPortraitPicker()">Porträt</button><button onclick="resetHero()">Zurücksetzen</button></div></div></div><div class="hero-tabs">${tabs}</div><div id="heroPane"></div>`;renderHeroPane()}
function renderHeroPane(){const h=currentHero(),p=document.getElementById("heroPane");if(!h||!p)return;if(heroTab==="overview")renderOverview(h,p);if(heroTab==="skills")renderSkills(h,p);if(heroTab==="attacks")renderAttacks(h,p);if(heroTab==="abilities")renderAbilities(h,p);if(heroTab==="inventory")renderInventory(h,p)}
function renderOverview(h,p){const hpPct=Math.max(0,Math.min(100,Math.round(h.hp/h.maxHp*100)));p.innerHTML=`<div class="dark-panel"><div class="hp-control"><span class="hp-number help-tappable" data-help="HP">${valueIcon('HP','value-icon hp-icon')}<b>${h.hp} / ${h.maxHp}</b></span><div class="hp-bar"><div class="hp-fill" style="width:${hpPct}%"></div></div><button onclick="changeHp(-1)">−</button><button onclick="changeHp(1)">＋</button><button onclick="setHp()">setzen</button></div><div class="quick-stats"><button class="quick" data-help="AC">${valueIcon('AC')}<b>${h.ac}</b><small>RK</small></button><button class="quick" data-help="INIT">${valueIcon('INIT')}<b>${fmt(attrMod(h.stats.DEX))}</b><small>Initiative</small></button><button class="quick" data-help="SPEED">${valueIcon('SPEED')}<b>${h.speed}m</b><small>Bewegung</small></button><button class="quick" data-help="PROF">${valueIcon('PROF')}<b>${fmt(h.prof)}</b><small>Übung</small></button><button class="quick" data-help="LEVEL">${valueIcon('LEVEL')}<b>${h.level}</b><small>Stufe</small></button></div><div class="roll-mode"><span class="roll-mode-help help-tappable" data-help="ADV">Wurfmodus</span><button class="${heroRollMode==='normal'?'on':''}" onclick="setHeroRollMode('normal')">Normal</button><button class="${heroRollMode==='adv'?'on':''}" onclick="setHeroRollMode('adv')">Vorteil</button><button class="${heroRollMode==='dis'?'on':''}" onclick="setHeroRollMode('dis')">Nachteil</button></div></div>${renderXpBar(h)}<div class="parchment"><div class="section-head"><h3 class="icon-heading">${valueIcon('PROF')}Attribute</h3><button class="gold" onclick="beginLevelUp()">${valueIcon('LEVEL','button-icon')}Stufenaufstieg</button></div><div class="hint-box">Gold markierte Bezeichnungen können für Erklärungen angetippt werden.</div><div class="attr-grid">${Object.entries(h.stats).map(([k,v])=>helpAttrCard(k,v)).join("")}</div>${renderLevelBox()}</div>`}
function beginLevelUp(){const h=currentHero();levelDraft={next:h.level+1,stats:{...h.stats},points:ASI_LEVELS.has(h.level+1)?2:0,startStats:{...h.stats}};renderHeroPane()}
function renderLevelBox(){if(!levelDraft)return"";const rows=Object.entries(levelDraft.stats).map(([k,v])=>`<div class="level-stat-row"><span>${ATTR_NAMES[k]}</span><span>${v}</span><button onclick="levelPoint('${k}',-1);event.stopPropagation()">−</button><button onclick="levelPoint('${k}',1);event.stopPropagation()">＋</button></div>`).join("");return `<div class="level-box"><div class="level-title"><div><b>Aufstieg auf Stufe ${levelDraft.next}</b><div class="muted">${ASI_LEVELS.has(levelDraft.next)?'Du erhältst 2 Attributspunkte.':'Diese Stufe gibt nach der vereinfachten Regel keine Attributspunkte.'}</div></div><div class="level-points">${levelDraft.points}</div></div>${ASI_LEVELS.has(levelDraft.next)?rows:'<div class="hint-box">Attributspunkte gibt es auf Stufe 4, 8, 12, 16 und 19. Der Übungsbonus steigt automatisch mit der Stufe.</div>'}<div class="button-row"><button onclick="cancelLevelUp()">Abbrechen</button><button class="gold" onclick="confirmLevelUp()" ${levelDraft.points>0?'disabled':''}>Stufe übernehmen</button></div></div>`}
function levelPoint(k,d){if(!levelDraft)return;if(d>0){if(levelDraft.points<=0||levelDraft.stats[k]>=20)return;levelDraft.stats[k]++;levelDraft.points--}else{if(levelDraft.stats[k]<=levelDraft.startStats[k])return;levelDraft.stats[k]--;levelDraft.points++}renderHeroPane()}
function cancelLevelUp(){levelDraft=null;renderHeroPane()}
function confirmLevelUp(){if(!levelDraft||levelDraft.points>0)return;const h=currentHero();h.level=levelDraft.next;h.stats={...levelDraft.stats};h.prof=profForLevel(h.level);h.xp=Math.max(Number(h.xp)||0,XP_THRESHOLDS[h.level]||0);levelDraft=null;save();renderHero();renderParty();renderGameMode()}
function setHeroRollMode(m){heroRollMode=m;renderHeroPane()}
function changeHp(n){const h=currentHero();h.hp=Math.max(0,Math.min(h.maxHp,h.hp+n));save();renderHeroPane();renderParty();renderGameMode()}function setHp(){const h=currentHero(),x=prompt("Aktuelle HP:",h.hp);if(x!==null&&!Number.isNaN(Number(x))){h.hp=Math.max(0,Math.min(h.maxHp,Number(x)));save();renderHeroPane();renderParty();renderGameMode()}}
function renderSkills(h,p){p.innerHTML=`<div class="parchment"><div class="section-head"><h3 class="help-tappable icon-heading" data-help="SKILL">${valueIcon('SKILL')}Fertigkeiten</h3><button onclick="toggleSkillEdit()">${editingSkills?'Fertig':'Geübte ändern'}</button></div><div class="hint-box">Gold markierte Namen öffnen Erklärungen. Das Würfelsiegel würfelt die Probe.</div>${Object.keys(SKILLS).map(s=>`<div class="list-row"><span class="skill-label help-tappable" data-skill-help="${safeText(s)}">${h.proficiencies.includes(s)?'<span class="skill-prof">◆</span>':''}<b>${safeText(s)}</b> <small>(${SKILLS[s]})</small></span>${editingSkills?`<button onclick="toggleProficiency('${s.replace(/'/g,"\'")}')">${h.proficiencies.includes(s)?'geübt ✓':'ungeübt'}</button>`:`<button class="roll-seal" onclick="rollCheck('${s.replace(/'/g,"\'")}')">${diceIcon(20)}<span>${fmt(skillBonus(h,s))}</span></button>`}</div>`).join("")}</div>`}
function toggleSkillEdit(){editingSkills=!editingSkills;renderHeroPane()}function toggleProficiency(s){const h=currentHero(),i=h.proficiencies.indexOf(s);if(i>=0)h.proficiencies.splice(i,1);else h.proficiencies.push(s);save();renderHeroPane()}
function renderAttacks(h,p){const cards=(h.attacks||[]).map((a,i)=>`<div class="attack-card"><b class="help-tappable icon-heading" data-help="ATTACK">${valueIcon('ATTACK')}${safeText(a.name)}</b><div>${safeText(a.stat||'')} · Angriff ${fmt(a.bonus)} · Schaden ${safeText(a.damage)}</div><div class="attack-actions"><button class="roll-seal" onclick="rollAttack(${i})">${diceIcon(20)}<span>Angriff</span></button><button class="roll-seal" onclick="rollDamage('${String(a.damage).replace(/'/g,"\\'")}','${String(a.name).replace(/'/g,"\\'")}')">${diceIcon((String(a.damage).match(/W(\d+)/i)||[])[1]||20)}<span>Schaden</span></button><button onclick="editAttack(${i})">Bearbeiten</button><button class="danger" onclick="removeAttack(${i})">Löschen</button></div>${editingAttack===i?attackEditor(a,i):''}</div>`).join("")||"<p>Noch keine Angriffe.</p>";p.innerHTML=`<div class="parchment"><div class="section-head"><h3 class="help-tappable icon-heading" data-help="ATTACK">${valueIcon('ATTACK')}Angriffe</h3><button class="gold" onclick="editAttack(-2)">＋ Angriff</button></div>${cards}${editingAttack===-2?attackEditor({name:'',stat:'STR',bonus:0,damage:'1W6'},-2):''}</div>`}
function attackEditor(a,i){return `<div class="inline-editor"><input id="eaName" value="${safeText(a.name)}" placeholder="Name"><div class="two"><label>Attribut<select id="eaStat">${['STR','DEX','INT','WIS','CHA'].map(x=>`<option ${x===a.stat?'selected':''}>${x}</option>`).join('')}</select></label><label>Bonus<input id="eaBonus" type="number" value="${Number(a.bonus)||0}"></label><label>Schaden<input id="eaDamage" value="${safeText(a.damage||'1W6')}"></label></div><div class="button-row"><button onclick="editingAttack=-1;renderHeroPane()">Abbrechen</button><button class="gold" onclick="saveAttack(${i})">Speichern</button></div></div>`}
function editAttack(i){editingAttack=i;renderHeroPane()}function saveAttack(i){const h=currentHero(),a={name:eaName.value.trim(),stat:eaStat.value,bonus:+eaBonus.value||0,damage:eaDamage.value.trim()||'1W6'};if(!a.name)return alert('Bitte einen Namen eingeben.');if(i===-2)h.attacks.push(a);else h.attacks[i]=a;editingAttack=-1;save();renderHeroPane();renderGameMode()}function removeAttack(i){if(confirm('Angriff löschen?')){currentHero().attacks.splice(i,1);save();renderHeroPane();renderGameMode()}}
function renderAbilities(h,p){const cards=(h.abilities||[]).map((a,i)=>`<div class="ability-card"><b class="help-tappable icon-heading" data-help="ABILITY">${valueIcon('ABILITY')}${safeText(a.name)}</b><div>${safeText(a.text)}</div><div class="card-actions"><button onclick="editAbility(${i})">Bearbeiten</button><button class="danger" onclick="removeAbility(${i})">Löschen</button></div>${editingAbility===i?abilityEditor(a,i):''}</div>`).join("")||"<p>Noch keine Fähigkeiten.</p>";p.innerHTML=`<div class="parchment"><div class="section-head"><h3 class="help-tappable icon-heading" data-help="ABILITY">${valueIcon('ABILITY')}Fähigkeiten</h3><button class="gold" onclick="editAbility(-2)">＋ Fähigkeit</button></div>${cards}${editingAbility===-2?abilityEditor({name:'',text:''},-2):''}</div>`}
function abilityEditor(a,i){return `<div class="inline-editor"><input id="ebName" value="${safeText(a.name)}" placeholder="Name"><textarea id="ebText" rows="3" placeholder="Kurze Beschreibung">${safeText(a.text)}</textarea><div class="button-row"><button onclick="editingAbility=-1;renderHeroPane()">Abbrechen</button><button class="gold" onclick="saveAbility(${i})">Speichern</button></div></div>`}
function editAbility(i){editingAbility=i;renderHeroPane()}function saveAbility(i){const h=currentHero(),a={name:ebName.value.trim(),text:ebText.value.trim()};if(!a.name||!a.text)return alert('Name und Beschreibung eingeben.');if(i===-2)h.abilities.push(a);else h.abilities[i]=a;editingAbility=-1;save();renderHeroPane();renderGameMode()}function removeAbility(i){if(confirm('Fähigkeit löschen?')){currentHero().abilities.splice(i,1);save();renderHeroPane();renderGameMode()}}
function renderInventory(h,p){p.innerHTML=`<div class="parchment"><h3 class="icon-heading">${layoutIcon('INVENTORY','value-icon')}Inventar</h3>${(h.inventory||[]).map((x,i)=>`<div class="list-row"><span>${safeText(x)}</span><button onclick="removeItem(${i})">−</button></div>`).join('')}<div class="inventory-add"><input id="newItem" placeholder="Neuer Gegenstand"><button class="gold" onclick="addItem()">＋</button></div></div>`}function addItem(){const h=currentHero(),i=newItem;if(i.value.trim()){h.inventory.push(i.value.trim());save();renderHeroPane()}}function removeItem(i){if(confirm('Gegenstand entfernen?')){currentHero().inventory.splice(i,1);save();renderHeroPane()}}
function setHelpIcon(key){const icon=HELP_ICONS[key]||'skill';helpIcon.textContent='';helpIcon.style.backgroundImage=`url("help-${icon}-v53.webp")`}
function showHelp(k){const d=HELP[k]||[k,"Kurze Hilfe ist hierfür noch nicht hinterlegt.",""];helpTitle.textContent=d[0];helpText.textContent=d[1];helpExtra.textContent=d[2];setHelpIcon(k);helpOverlay.classList.add('open');document.body.classList.add('sheet-open')}function showSkillHelp(s){helpTitle.textContent=s;helpText.textContent=SKILL_HELP[s]||HELP.SKILL[1];helpExtra.textContent=`Verwendetes Attribut: ${ATTR_NAMES[SKILLS[s]]} (${SKILLS[s]}). ${currentHero()?.proficiencies.includes(s)?'Dein Held ist darin geübt.':'Dein Held ist darin derzeit nicht geübt.'}`;setHelpIcon(SKILLS[s]||'SKILL');helpOverlay.classList.add('open');document.body.classList.add('sheet-open')}
function creatorStep(n){document.querySelectorAll('.creator-step').forEach(x=>x.classList.remove('active'));document.querySelector(`.creator-step[data-step="${n}"]`).classList.add('active');for(let i=1;i<=4;i++)document.getElementById('prog'+i).classList.toggle('on',i<=n);if(n===2)renderCreationStats();if(n===3)renderCreationSkills()}
function openCreator(){closeOverlay('chooser');resetCreator();creator.classList.add('open');creatorStep(1)}
function resetCreator(){creationMode='points';creationStats={STR:8,DEX:8,CON:8,INT:8,WIS:8,CHA:8};creationRollDetails={};creationSkills=[];['cName','cRole','cStory','cAttackName','cAbilities','cInventory'].forEach(id=>{const e=document.getElementById(id);if(e)e.value=''});if(cImage)cImage.value='';cHP.value=12;cAC.value=13;cSpeed.value=9;cProf.value=2;cAttackBonus.value=2;cAttackDamage.value='1W8+2'}
function creationNext(){if(creationMode==='points'&&27-pointsSpent()>0)return alert('Bitte verteile zuerst alle 27 Punkte.');creatorStep(3)}
function setCreationMode(m){creationMode=m;modePoints.classList.toggle('on',m==='points');modeRoll.classList.toggle('on',m==='roll');if(m==='points'){creationStats={STR:8,DEX:8,CON:8,INT:8,WIS:8,CHA:8};creationRollDetails={}}else rollAllCreationStats();renderCreationStats()}
function pointsSpent(){return Object.values(creationStats).reduce((s,v)=>s+(POINT_COST[v]??99),0)}
function creationPoint(k,d){const v=creationStats[k];if(creationMode!=='points')return;if(d>0){const nv=v+1;if(nv>15)return;const cost=(POINT_COST[nv]-POINT_COST[v]);if(pointsSpent()+cost>27)return;creationStats[k]=nv}else if(v>8)creationStats[k]=v-1;renderCreationStats()}
function roll4d6(){const r=[1,2,3,4].map(()=>rollDie(6)).sort((a,b)=>a-b);return {value:r[1]+r[2]+r[3],detail:r.join(', ')+' → '+(r[1]+r[2]+r[3])}}
function rollAllCreationStats(){for(const k of Object.keys(creationStats)){const r=roll4d6();creationStats[k]=r.value;creationRollDetails[k]=r.detail}renderCreationStats()}
function rerollCreationStat(k){const r=roll4d6();creationStats[k]=r.value;creationRollDetails[k]=r.detail;renderCreationStats()}
function renderCreationStats(){if(!creationStatsGrid)return;modePoints.classList.toggle('on',creationMode==='points');modeRoll.classList.toggle('on',creationMode==='roll');const remain=27-pointsSpent();creationBudget.textContent=creationMode==='points'?`Noch ${remain} von 27 Punkten verfügbar.`:'Jeder Wert wird mit 4W6 gewürfelt; der niedrigste Würfel entfällt.';rollControls.hidden=creationMode!=='roll';creationStatsGrid.innerHTML=Object.entries(creationStats).map(([k,v])=>`<div class="creation-stat"><div class="creation-stat-head"><span class="help-tappable icon-heading" data-help="${k}">${valueIcon(k)}<b>${ATTR_NAMES[k]}</b></span><strong>${v}</strong></div>${creationMode==='points'?`<div class="creation-stat-actions"><button onclick="creationPoint('${k}',-1)">−</button><button onclick="creationPoint('${k}',1)">＋</button></div>`:`<div class="roll-detail">${safeText(creationRollDetails[k]||'')}</div><button class="roll-seal" onclick="rerollCreationStat('${k}')">${diceIcon(6)}<span>neu würfeln</span></button>`}</div>`).join('')}
function renderCreationSkills(){cSkillPicker.innerHTML=Object.keys(SKILLS).map(s=>`<div class="skill-choice"><button class="${creationSkills.includes(s)?'on':''}" onclick="toggleCreationSkill('${s.replace(/'/g,"\'")}');return false">${safeText(s)}</button><button class="mini-help" data-skill-help="${safeText(s)}" type="button" aria-label="${safeText(s)} erklären"><img src="help-${String(SKILLS[s]).toLowerCase()}-v53.webp" alt=""></button></div>`).join('')}
function toggleCreationSkill(s){const i=creationSkills.indexOf(s);if(i>=0)creationSkills.splice(i,1);else{if(creationSkills.length>=3)return alert('Maximal 3 geübte Fertigkeiten bei der Erstellung.');creationSkills.push(s)}renderCreationSkills()}
function imageFileToDataURL(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const maxW=900,maxH=1350,scale=Math.min(1,maxW/img.width,maxH/img.height),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.82))};img.onerror=reject;img.src=r.result};r.onerror=reject;r.readAsDataURL(file)})}
async function createHero(){const name=cName.value.trim();if(!name)return alert('Bitte einen Namen eingeben.');const img=await imageFileToDataURL(cImage.files[0]);const abs=cAbilities.value.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{let p=x.split(':');return {name:p.shift().trim(),text:p.join(':').trim()||'Besondere Fähigkeit.'}});const atk=cAttackName.value.trim();const hp=+cHP.value||10;const h={id:'custom-'+Date.now(),name,role:cRole.value.trim()||'Abenteurer',image:img||'backgrounds-cosmic-v42.webp',level:1,story:cStory.value.trim(),maxHp:hp,hp,ac:+cAC.value||10,speed:+cSpeed.value||9,prof:+cProf.value||2,stats:{...creationStats},proficiencies:[...creationSkills],abilities:abs,attacks:atk?[{name:atk,stat:cAttackStat.value,bonus:+cAttackBonus.value||0,damage:cAttackDamage.value.trim()||'1W6'}]:[],inventory:cInventory.value.split('\n').map(x=>x.trim()).filter(Boolean),notes:''};state.heroes.push(h);state.current=h.id;save();closeOverlay('creator');heroTab='overview';renderHero();renderParty();switchView('hero')}
function openBasicEdit(){const h=currentHero();if(!h)return;beName.value=h.name;beRole.value=h.role;beStory.value=h.story||'';beMaxHp.value=h.maxHp;beAC.value=h.ac;beSpeed.value=h.speed;basicEditOverlay.classList.add('open')}
function saveBasicEdit(){const h=currentHero();if(!h)return;const newMax=Math.max(1,+beMaxHp.value||h.maxHp);h.name=beName.value.trim()||h.name;h.role=beRole.value.trim()||h.role;h.story=beStory.value.trim();h.maxHp=newMax;h.hp=Math.min(h.hp,newMax);h.ac=Math.max(1,+beAC.value||h.ac);h.speed=Math.max(0,+beSpeed.value||h.speed);save();closeOverlay('basicEditOverlay');renderHero();renderParty();renderChooser();renderGameMode()}
function openPortraitPicker(){if(currentHero())portraitOverlay.classList.add('open')}async function changePortrait(e){const f=e.target.files[0];if(!f)return;currentHero().image=await imageFileToDataURL(f);save();closeOverlay('portraitOverlay');renderHero();renderChooser();renderParty();renderGameMode();portraitFile.value=''}function resetPortrait(){const h=currentHero(),b=baseHeroById(h.id);if(!b)return alert('Eigene Helden haben kein hinterlegtes Originalporträt.');h.image=b.image;save();closeOverlay('portraitOverlay');renderHero();renderChooser();renderParty();renderGameMode()}function resetHero(){const h=currentHero(),b=h&&baseHeroById(h.id);if(!b)return alert('Eigene Helden haben keine feste Vorlage.');if(confirm('Diesen Standardhelden vollständig auf die Originalwerte zurücksetzen?')){state.heroes[state.heroes.findIndex(x=>x.id===h.id)]=deepClone(b);save();renderHero();renderChooser();renderParty();renderGameMode()}}
function rollDie(s){return 1+Math.floor(Math.random()*s)}function d20(mode){const a=rollDie(20),b=rollDie(20);if(mode==='adv')return{raw:Math.max(a,b),display:`${a} / ${b}`};if(mode==='dis')return{raw:Math.min(a,b),display:`${a} / ${b}`};return{raw:a,display:String(a)}}function parseDamage(expr){const m=String(expr).toUpperCase().match(/(\d+)W(\d+)([+-]\d+)?/);if(!m)return null;const count=+m[1],sides=+m[2],bonus=+(m[3]||0),rolls=[];for(let i=0;i<count;i++)rolls.push(rollDie(sides));return{sides,rolls,bonus,total:rolls.reduce((a,b)=>a+b,0)+bonus}}
function gameRollMarkup(r){if(!r)return `<div class="game-roll-empty">${diceIcon(20,'game-roll-die')}<div><b>Würfelergebnis</b><small>Wähle unten eine Aktion.</small></div></div>`;return `${diceIcon(r.sides,'game-roll-die')}<div class="game-roll-copy"><small>${safeText(r.title)}</small><strong>${r.total}</strong><span>${safeText(r.detail||String(r.total))}</span></div>`}
function animateRoll({sides,title,raw,display,total,detail}){const gameBox=document.getElementById('gameModeRollResult'),inGame=gameMode&&gameMode.classList.contains('open')&&gameBox;if(inGame){gameBox.className='game-roll-result rolling';gameBox.innerHTML=`${diceIcon(sides,'game-roll-die')}<div class="game-roll-copy"><small>${safeText(title)}</small><strong>…</strong><span>Der Würfel rollt</span></div>`;setTimeout(()=>{const verdict=sides===20&&raw===20?' · KRITISCH!':sides===20&&raw===1?' · PATZER!':'';gameBox.className='game-roll-result landed '+(raw===20&&sides===20?'crit-roll':raw===1&&sides===20?'fumble-roll':'');gameBox.innerHTML=gameRollMarkup({sides,title,total,detail:(detail||display)+verdict});addRollHistory(title,detail||display,total,raw,sides)},650);return}switchView('dice');const art=diceAsset(sides);dieVisual.style.backgroundImage=`url("dice-w${art}-v55.webp")`;dieType.textContent='W'+sides;dieNumber.textContent='';diceCaption.textContent=title;diceResult.textContent='Der Würfel rollt …';dieVisual.classList.remove('rolling','landed');void dieVisual.offsetWidth;dieVisual.classList.add('rolling');setTimeout(()=>{dieVisual.classList.remove('rolling');dieVisual.classList.add('landed');dieNumber.textContent=raw;dieNumber.className='die-number '+(sides===20&&raw===20?'crit':sides===20&&raw===1?'fumble':'');const verdict=sides===20&&raw===20?' · KRITISCH!':sides===20&&raw===1?' · PATZER!':'';diceResult.innerHTML=`${safeText(display)}${total!==raw?` → <b>${total}</b>`:''}${verdict}`;addRollHistory(title,detail||display,total,raw,sides)},1050)}function addRollHistory(title,detail,total,raw,sides){state.rollHistory.unshift({title,detail,total,raw,sides,time:new Date().toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})});state.rollHistory=state.rollHistory.slice(0,15);save();renderRollHistory()}function freeRoll(sides){const bonus=Number(freeMod.value||0),mode=freeAdv.value;if(sides===20){const r=d20(mode);animateRoll({sides,title:'Freier W20-Wurf',raw:r.raw,display:r.display,total:r.raw+bonus,detail:`${r.display} ${fmt(bonus)}`})}else{const raw=rollDie(sides);animateRoll({sides,title:'Freier W'+sides+'-Wurf',raw,display:String(raw),total:raw+bonus,detail:`${raw} ${fmt(bonus)}`})}}function rollCheck(s){const h=currentHero(),bonus=skillBonus(h,s),r=d20(heroRollMode);animateRoll({sides:20,title:h.name+' · '+s,raw:r.raw,display:r.display,total:r.raw+bonus,detail:`${r.display} ${fmt(bonus)}`})}function rollInitiative(){const h=currentHero(),bonus=attrMod(h.stats.DEX),r=d20(heroRollMode);animateRoll({sides:20,title:h.name+' · Initiative',raw:r.raw,display:r.display,total:r.raw+bonus,detail:`${r.display} ${fmt(bonus)}`})}function rollQuickD20(){const h=currentHero(),r=d20(heroRollMode);animateRoll({sides:20,title:h.name+' · Freier W20',raw:r.raw,display:r.display,total:r.raw,detail:r.display})}function rollAttack(i){const h=currentHero(),a=h.attacks[i],r=d20(heroRollMode);animateRoll({sides:20,title:h.name+' · '+a.name,raw:r.raw,display:r.display,total:r.raw+Number(a.bonus),detail:`Angriff: ${r.display} ${fmt(a.bonus)}`})}function rollDamage(expr,name){const x=parseDamage(expr);if(!x)return alert('Schadensformel nicht erkannt.');const shown=x.rolls.join(' + ')+(x.bonus?` ${fmt(x.bonus)}`:'');animateRoll({sides:x.sides,title:name+' · Schaden',raw:x.rolls[0],display:shown,total:x.total,detail:expr+' = '+x.total})}function renderRollHistory(){rollHistory.innerHTML=(state.rollHistory||[]).map(r=>`<div class="history-row">${diceIcon(r.sides,'dice-history-icon')}<span><b>${safeText(r.title)}</b><br><small class="muted">${safeText(r.detail)} · ${r.time}</small></span><b>${r.total}</b></div>`).join('')||'<p class="muted">Noch keine Würfe.</p>'}function initDiceControls(){if(!diceButtons)return;diceButtons.innerHTML='';for(const n of DICE_SIDES){const b=document.createElement('button');b.type='button';b.className='dice-choice';b.innerHTML=`${diceIcon(n,'dice-choice-icon')}<span>W${n}</span>`;b.addEventListener('click',()=>freeRoll(n));diceButtons.appendChild(b)}}
function savePersonalNotes(){const h=currentHero();if(h){h.notes=personalNotes.value;save()}}function renderNotes(){personalNotes.value=currentHero()?.notes||'';renderJournal()}function setJournalFilter(f,btn){journalFilter=f;document.querySelectorAll('.journal-filter .chip').forEach(x=>x.classList.remove('active'));btn.classList.add('active');renderJournal()}function addJournalEntry(){const title=entryTitle.value.trim();if(!title)return;state.journal.unshift({type:entryType.value,title,text:entryText.value.trim(),date:new Date().toLocaleDateString('de-DE')});entryTitle.value='';entryText.value='';save();renderJournal()}function editJournal(i){const e=state.journal[i],t=prompt('Titel:',e.title);if(t===null)return;const x=prompt('Text:',e.text);if(x===null)return;e.title=t;e.text=x;save();renderJournal()}function deleteJournal(i){if(confirm('Eintrag löschen?')){state.journal.splice(i,1);save();renderJournal()}}function renderJournal(){const filtered=state.journal.map((x,i)=>({...x,_i:i})).filter(x=>journalFilter==='Alle'||x.type===journalFilter);journalEntries.innerHTML=filtered.map(e=>`<div class="entry"><div class="entry-actions"><button onclick="editJournal(${e._i})">✎</button><button onclick="deleteJournal(${e._i})">✕</button></div><small>${safeText(e.type)} · ${safeText(e.date)}</small><b>${safeText(e.title)}</b><div>${safeText(e.text)}</div></div>`).join('')||'<p class="dark-text muted">Noch keine Einträge.</p>'}
function renderRules(){/* Regelwerk ist statisch im HTML und deshalb immer sichtbar. */}
function renderParty(){partyRoster.innerHTML=state.heroes.map(h=>`<button class="party-mini" onclick="chooseHero('${h.id}')"><img src="${h.image}" alt=""><div><b>${safeText(h.name)}</b><small>${safeText(h.role)}<br>HP ${h.hp}/${h.maxHp} · Stufe ${h.level}</small></div></button>`).join('')}
function exportHero(){const h=currentHero();if(h)downloadJSON(h,h.name.replace(/\s+/g,'_')+'_Eldanor.json')}function importHero(e){const f=e.target.files[0];if(!f)return;readJSON(f,obj=>{obj.id='import-'+Date.now();state.heroes.push(normalizeState({heroes:[obj]}).heroes[0]);state.current=obj.id;save();renderHero();renderParty();openHeroChooser()})}function exportCampaign(){downloadJSON({journal:state.journal,rollHistory:state.rollHistory},'Eldanor_Chronik.json')}function importCampaign(e){const f=e.target.files[0];if(!f)return;readJSON(f,obj=>{if(Array.isArray(obj.journal))state.journal=obj.journal;if(Array.isArray(obj.rollHistory))state.rollHistory=obj.rollHistory;save();renderJournal();renderRollHistory();alert('Chronik importiert.')})}function deleteCurrentCustomHero(){const h=currentHero();if(!h)return;if(baseHeroById(h.id))return alert('Standardhelden können nicht gelöscht werden.');if(confirm('Diesen eigenen Helden löschen?')){state.heroes=state.heroes.filter(x=>x.id!==h.id);state.current=BASE_HEROES[0].id;save();renderHero();renderParty();openHeroChooser()}}function downloadJSON(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function readJSON(file,cb){const r=new FileReader();r.onload=()=>{try{cb(JSON.parse(r.result))}catch(e){alert('Datei konnte nicht gelesen werden.')}};r.readAsText(file)}
function gameQuickSkills(h){const list=[...(h.proficiencies||[]),'Wahrnehmung','Heimlichkeit','Athletik','Überreden'];return list.filter((s,i,a)=>SKILLS[s]&&a.indexOf(s)===i).slice(0,4)}
function setGameRollMode(m){heroRollMode=m;renderGameMode()}
function saveHeroXp(){const h=currentHero(),input=document.getElementById('gameXpInput'),value=Number(input&&input.value);if(!h||!Number.isFinite(value)||value<0)return alert('Bitte gültige Erfahrungspunkte eingeben.');h.xp=Math.round(value);save();renderHeroPane();renderGameMode()}
function startLevelUpFromGameMode(){const h=currentHero();if(!h||h.level>=20)return;closeOverlay('gameMode');heroTab='overview';switchView('hero');renderHero();beginLevelUp()}
function openGameMode(){renderGameMode();gameMode.classList.add('open')}
function renderGameMode(){const h=currentHero();if(!h)return;const skills=gameQuickSkills(h).map(s=>`<button class="quick-action-icon" onclick="rollCheck('${s.replace(/'/g,"\\'")}')">${valueIcon(SKILLS[s])}<span><b>${safeText(s)}</b><small>${fmt(skillBonus(h,s))}</small></span></button>`).join('');const attacks=(h.attacks||[]).map((a,i)=>`<div class="game-attack-row"><div>${valueIcon('ATTACK')}<span><b>${safeText(a.name)}</b><small>Angriff ${fmt(a.bonus)} · Schaden ${safeText(a.damage)}</small></span></div><button onclick="rollAttack(${i})">W20</button><button onclick="rollDamage('${String(a.damage).replace(/'/g,"\\'")}','${String(a.name).replace(/'/g,"\\'")}')">Schaden</button></div>`).join('')||'<p class="muted">Noch keine Angriffe angelegt.</p>';const abilities=(h.abilities||[]).slice(0,4).map(a=>`<details class="game-ability"><summary>${valueIcon('ABILITY')}<b>${safeText(a.name)}</b></summary><p>${safeText(a.text)}</p></details>`).join('');const last=(state.rollHistory||[])[0];gameModeInner.innerHTML=`<div class="quickmode-card"><div class="herohead"><img src="${h.image}" alt=""><div><h2>${safeText(h.name)}</h2><div>${safeText(h.role)} · Stufe ${h.level}</div><div class="quickmode-values"><span>${valueIcon('HP')}<b>${h.hp}/${h.maxHp}</b> HP</span><span>${valueIcon('AC')}<b>${h.ac}</b> RK</span><span>${valueIcon('INIT')}<b>${fmt(attrMod(h.stats.DEX))}</b> Initiative</span><span>${valueIcon('SPEED')}<b>${h.speed} m</b> Bewegung</span><span>${valueIcon('PROF')}<b>${fmt(h.prof)}</b> Übung</span><span>${valueIcon('WIS')}<b>${10+skillBonus(h,'Wahrnehmung')}</b> passive Wahrn.</span></div></div></div></div><section class="game-section game-hp"><h3>${valueIcon('HP')}Trefferpunkte</h3><div class="game-hp-value"><b>${h.hp}</b><span>/ ${h.maxHp}</span></div><div class="game-hp-actions"><button onclick="changeHp(-5)">−5</button><button onclick="changeHp(-1)">−1</button><button onclick="setHp()">setzen</button><button onclick="changeHp(1)">+1</button><button onclick="changeHp(5)">+5</button></div></section><section class="game-section"><div class="game-section-head"><h3>${valueIcon('ADV')}Würfeln</h3><div class="game-roll-mode"><button class="${heroRollMode==='normal'?'on':''}" onclick="setGameRollMode('normal')">Normal</button><button class="${heroRollMode==='adv'?'on':''}" onclick="setGameRollMode('adv')">Vorteil</button><button class="${heroRollMode==='dis'?'on':''}" onclick="setGameRollMode('dis')">Nachteil</button></div></div><div id="gameModeRollResult" class="game-roll-result">${gameRollMarkup(last)}</div><div class="quick-actions game-common-actions"><button class="quick-action-icon" onclick="rollInitiative()">${valueIcon('INIT')}<span><b>Initiative</b><small>${fmt(attrMod(h.stats.DEX))}</small></span></button><button class="quick-action-icon" onclick="rollQuickD20()">${valueIcon('ADV')}<span><b>Freier W20</b><small>ohne Bonus</small></span></button>${skills}</div></section><section class="game-section"><h3>${valueIcon('ATTACK')}Angriffe & Schaden</h3><div class="game-attacks">${attacks}</div></section>${abilities?`<section class="game-section"><h3>${valueIcon('ABILITY')}Fähigkeiten im Blick</h3>${abilities}</section>`:''}${renderXpBar(h,true)}`}
function updateMapZoomLabel(){if(mapZoomLabel)mapZoomLabel.textContent=Math.round(mapScale*100)+' %'}
function mapZoom(delta,cx,cy){setMapScale(mapScale+delta,cx,cy)}
function setMapScale(next,cx,cy){const vp=mapViewport,old=mapScale;next=Math.max(1,Math.min(4,next));if(!vp||!worldMap)return;if(cx==null)cx=vp.clientWidth/2;if(cy==null)cy=vp.clientHeight/2;const wx=(vp.scrollLeft+cx)/old,wy=(vp.scrollTop+cy)/old;mapScale=next;worldMap.style.width=(mapScale*100)+'%';requestAnimationFrame(()=>{vp.scrollLeft=Math.max(0,wx*mapScale-cx);vp.scrollTop=Math.max(0,wy*mapScale-cy);updateMapZoomLabel()})}
function resetMap(){mapScale=1;worldMap.style.width='100%';mapViewport.scrollTo({left:0,top:0,behavior:'smooth'});updateMapZoomLabel()}
function fitMapIfNeeded(){if(!worldMap.style.width)worldMap.style.width=(mapScale*100)+'%';updateMapZoomLabel()}
function initMapGestures(){const vp=mapViewport;if(!vp)return;let pinch=null,lastTap={time:0,x:0,y:0},mouseDrag=null;const distance=(a,b)=>Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY);const localPoint=t=>{const r=vp.getBoundingClientRect();return{x:t.clientX-r.left,y:t.clientY-r.top}};vp.addEventListener('touchstart',e=>{if(e.touches.length===2){e.preventDefault();const a=e.touches[0],b=e.touches[1],r=vp.getBoundingClientRect(),cx=(a.clientX+b.clientX)/2-r.left,cy=(a.clientY+b.clientY)/2-r.top;pinch={dist:distance(a,b),scale:mapScale,wx:(vp.scrollLeft+cx)/mapScale,wy:(vp.scrollTop+cy)/mapScale}}},{passive:false});vp.addEventListener('touchmove',e=>{if(e.touches.length===2&&pinch){e.preventDefault();const a=e.touches[0],b=e.touches[1],r=vp.getBoundingClientRect(),cx=(a.clientX+b.clientX)/2-r.left,cy=(a.clientY+b.clientY)/2-r.top,next=Math.max(1,Math.min(4,pinch.scale*(distance(a,b)/Math.max(1,pinch.dist))));mapScale=next;worldMap.style.width=(mapScale*100)+'%';vp.scrollLeft=Math.max(0,pinch.wx*mapScale-cx);vp.scrollTop=Math.max(0,pinch.wy*mapScale-cy);updateMapZoomLabel()}},{passive:false});vp.addEventListener('touchend',e=>{if(e.touches.length<2)pinch=null;if(e.touches.length===0&&e.changedTouches.length===1){const t=e.changedTouches[0],now=Date.now(),dx=t.clientX-lastTap.x,dy=t.clientY-lastTap.y;if(now-lastTap.time<330&&Math.hypot(dx,dy)<35){e.preventDefault();const pt=localPoint(t);setMapScale(mapScale<1.75?2:1,pt.x,pt.y);lastTap={time:0,x:0,y:0}}else lastTap={time:now,x:t.clientX,y:t.clientY}}},{passive:false});vp.addEventListener('dblclick',e=>{const r=vp.getBoundingClientRect();setMapScale(mapScale<1.75?2:1,e.clientX-r.left,e.clientY-r.top)});vp.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();const r=vp.getBoundingClientRect();setMapScale(mapScale+(e.deltaY<0?.25:-.25),e.clientX-r.left,e.clientY-r.top)}},{passive:false});vp.addEventListener('mousedown',e=>{if(e.button!==0)return;mouseDrag={x:e.clientX,y:e.clientY,sl:vp.scrollLeft,st:vp.scrollTop};vp.classList.add('dragging')});window.addEventListener('mousemove',e=>{if(!mouseDrag)return;vp.scrollLeft=mouseDrag.sl-(e.clientX-mouseDrag.x);vp.scrollTop=mouseDrag.st-(e.clientY-mouseDrag.y)});window.addEventListener('mouseup',()=>{mouseDrag=null;vp.classList.remove('dragging')});updateMapZoomLabel()}
